-- posts: created by `forge generate scaffold` for PostgreSQL.
-- Identifiers are UUIDv7 values generated by the application; the
-- database never generates them. `version` is the optimistic lock.

CREATE TABLE "posts" (
    "id" uuid NOT NULL PRIMARY KEY,
    "title" text NOT NULL CONSTRAINT "posts_title_length" CHECK (char_length("title") <= 255),
    "body" text NOT NULL,
    "published" boolean NOT NULL,
    "version" bigint NOT NULL DEFAULT 1 CONSTRAINT "posts_version_positive" CHECK ("version" >= 1),
    "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP
);

REVOKE ALL ON TABLE "posts" FROM PUBLIC;

DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'app_runtime') THEN
        GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE "posts" TO app_runtime;
    END IF;
END
$$;
